<?php
use App\Models\Kelas; use App\Models\PilketosHakPilih; use App\Models\PilketosPeriode; use App\Models\Siswa; use Livewire\Attributes\Layout; use Livewire\WithPagination; use Livewire\Volt\Component;
new #[Layout('layouts.pilketos')] class extends Component { use WithPagination; public $periodes,$kelas; public ?int $periodeId=null,$kelasId=null; public string $gender='', $status=''; public function mount():void{$this->periodes=PilketosPeriode::latest('tahun')->get();$this->kelas=Kelas::orderBy('tingkat')->orderBy('nama')->get();$this->periodeId=$this->periodes->first()?->id;} public function updated($n):void{if(in_array($n,['periodeId','kelasId','gender','status']))$this->resetPage();} public function with():array{$p=PilketosPeriode::find($this->periodeId);if(!$p)return['pemilih'=>collect()];$s=Siswa::where('tahun',$p->tahun)->select('nis','kelas_id')->distinct();$q=PilketosHakPilih::where('periode_id',$p->id)->joinSub($s,'sp',fn($j)=>$j->on('pilketos_hak_pilih.nis','=','sp.nis'))->leftJoin('user_siswa','user_siswa.nis','=','pilketos_hak_pilih.nis')->leftJoin('kelas','kelas.id','=','sp.kelas_id')->select('pilketos_hak_pilih.*','user_siswa.name','kelas.tingkat','kelas.nama as nama_kelas')->when($this->kelasId,fn($q)=>$q->where('sp.kelas_id',$this->kelasId))->when($this->gender,fn($q)=>$q->where('kategori',$this->gender))->when($this->status,fn($q)=>$q->where('status',$this->status));return['pemilih'=>$q->orderBy('name')->paginate(25)];}}; ?>
<div><a wire:navigate href="{{route('guru.dashboard')}}">← Dashboard</a><h1 class="mt-4 text-3xl font-black">Monitoring pemilih</h1><div class="mt-5 flex flex-wrap gap-3"><select wire:model.live="periodeId">@foreach($periodes as $p)<option value="{{$p->id}}">{{$p->tahun}}</option>@endforeach</select><select wire:model.live="kelasId"><option value="">Semua kelas</option>@foreach($kelas as $k)<option value="{{$k->id}}">{{$k->tingkat}} {{$k->nama}}</option>@endforeach</select><select wire:model.live="gender"><option value="">Semua gender</option><option value="L">Putra</option><option value="P">Putri</option></select><select wire:model.live="status"><option value="">Semua status</option><option value="sudah_memilih">Sudah memilih</option><option value="belum_memilih">Belum memilih</option></select></div><div wire:loading.delay><x-skeleton variant="table"/></div><table wire:loading.remove class="mt-6 w-full bg-white"><thead><tr><th>Nama</th><th>Kelas</th><th>Status</th></tr></thead><tbody>@foreach($pemilih as $p)<tr><td>{{$p->name}}</td><td>{{$p->tingkat}} {{$p->nama_kelas}}</td><td>{{$p->status}}</td></tr>@endforeach</tbody></table>{{$pemilih->links()}}</div>
